        manufacturerGrid.addColumn(deleteColumn, "Delete");
        manufacturerGrid.setColumnWidth(editColumn, 75, Unit.PX);
        manufacturerGrid.setColumnWidth(deleteColumn, 75, Unit.PX);
    }
