import { ChangeDetectionStrategy, Component, OnInit, inject, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { ApiService } from '../core/api.service';
import { Manufacturer } from '../core/models';
import { MessageService } from '../core/message.service';

@Component({
  selector: 'app-edit-manufacturer',
  standalone: true,
  imports: [FormsModule],
  templateUrl: './edit-manufacturer.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EditManufacturerComponent implements OnInit {
  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  readonly manufacturer = input.required<Manufacturer>();
  readonly saved = output<Manufacturer>();
  readonly closed = output<void>();

  /** Working copy; only written back to the list once the server has saved it. */
  draft: Manufacturer = { name: '' };
  readonly saving = signal(false);

  ngOnInit(): void {
    this.draft = { ...this.manufacturer() };
  }

  save(): void {
    this.saving.set(true);
    this.api.saveManufacturer(this.draft).subscribe({
      next: (saved) => {
        this.messages.success('The manufacturer has been saved.');
        this.saved.emit(saved);
      },
      error: () => {
        this.saving.set(false);
        this.messages.error('The manufacturer could not be saved.');
      },
    });
  }

  close(): void {
    this.closed.emit();
  }
}

