/* Global styles: the page layout, tables, buttons and the popup shared by the screens. */
body {
  font-family: Arial, Helvetica, sans-serif;
  margin: 0;
  color: #222;
}

.content {
  width: 1000px;
  max-width: 100%;
  margin: 0 auto;
  padding: 10px 0;
}

.big-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 10px;
}

.big-title h2 {
  margin: 0;
}

.table-wrapper {
  margin-top: 20px;
}

table.grid {
  width: 100%;
  border-collapse: collapse;
}

table.grid th,
table.grid td {
  text-align: left;
  padding: 6px 8px;
  border-bottom: 1px solid #ddd;
}

table.grid th {
  background: #f1f6fb;
}

.col-id {
  width: 50px;
}

.col-rating {
  width: 60px;
}

.col-action {
  width: 75px;
}

button {
  cursor: pointer;
}

button.add-action,
button.action,
.popup button {
  font-size: 13px;
  padding: 4px 10px;
}

button:disabled {
  cursor: default;
  opacity: 0.5;
}

