.message {
  pointer-events: auto;
  display: flex;
  justify-content: space-between;
  gap: 10px;
  width: 1000px;
  max-width: calc(100% - 20px);
  margin: 6px auto;
  padding: 8px 12px;
  border-radius: 3px;
  box-sizing: border-box;
}

.message.success {
  background: #dff0d8;
  color: #3c763d;
  border: 1px solid #c4e3b1;
}

.message.error {
  background: #f2dede;
  color: #a94442;
  border: 1px solid #ebccd1;
}

.message .close {
  cursor: pointer;
  font-weight: bold;
}

