// Drives headless Chromium over CDP through the same scenarios as e2e/*.feature,
// using the same element ids / table xpaths / button selectors as the Selenium page objects.
const WebSocket = require('/work/node_modules/ws');
const { spawn } = require('child_process');

const BASE = 'http://localhost:8888/ng/';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const q = (s) => JSON.stringify(s);

let failures = 0;
const results = [];

async function main() {
  const profile = '/tmp/cr-profile-' + Date.now();
  const chrome = spawn('/usr/bin/chromium', [
    '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
    '--remote-debugging-port=9333', '--user-data-dir=' + profile, '--window-size=1280,900', 'about:blank',
  ], { stdio: 'ignore' });

  let targets;
  for (let i = 0; i < 100; i++) {
    try { targets = await (await fetch('http://127.0.0.1:9333/json/list')).json(); break; } catch { await sleep(200); }
  }
  const page = targets.find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl, { perMessageDeflate: false });
  await new Promise((res, rej) => { ws.on('open', res); ws.on('error', rej); });

  let nextId = 0;
  const pending = new Map();
  ws.on('message', (m) => {
    const msg = JSON.parse(m);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  });
  const send = (method, params = {}) => new Promise((res) => {
    const id = ++nextId; pending.set(id, res); ws.send(JSON.stringify({ id, method, params }));
  });
  const evaluate = async (expr) => {
    const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
    if (r.result.exceptionDetails) throw new Error('JS error: ' + JSON.stringify(r.result.exceptionDetails).slice(0, 500));
    return r.result.result.value;
  };
  const waitFor = async (expr, what, timeout = 10000) => {
    const end = Date.now() + timeout;
    while (Date.now() < end) { if (await evaluate(expr)) return; await sleep(100); }
    throw new Error('timeout waiting for ' + what);
  };
  const isVisible = (sel) => `(() => { const el = document.querySelector(${q(sel)}); if (!el) return false;
      const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0; })()`;
  const exists = (sel) => `!!document.querySelector(${q(sel)})`;
  const clickSel = async (sel) => {
    await waitFor(`${isVisible(sel)} && !document.querySelector(${q(sel)}).disabled`, 'clickable ' + sel);
    await evaluate(`document.querySelector(${q(sel)}).click()`);
  };
  const typeInto = async (sel, text) => {
    await waitFor(isVisible(sel), 'visible ' + sel);
    await evaluate(`(() => { const el = document.querySelector(${q(sel)}); el.focus(); try { el.select(); } catch (e) {} return true; })()`);
    await send('Input.insertText', { text });
  };
  // Mirrors PageWithEditTable: rows are tbody[1]/tr, cell index comes from thead th text.
  const rowCount = (tableId) => evaluate(`document.querySelectorAll(${q('#' + tableId + ' > tbody:first-of-type > tr')}).length`);
  const cellText = (tableId, colName, row) => evaluate(`(() => {
      const t = document.getElementById(${q(tableId)});
      const ths = [...t.querySelectorAll('thead th')].map(th => th.textContent.trim());
      const idx = ths.indexOf(${q(colName)}) + 1;
      const td = t.querySelector(':scope > tbody:first-of-type > tr:nth-child(${row}) > td:nth-child(' + idx + ')');
      return td ? td.textContent.trim() : null; })()`);
  const lastRowCell = (tableId, colName) => evaluate(`(() => {
      const t = document.getElementById(${q(tableId)});
      const ths = [...t.querySelectorAll('thead th')].map(th => th.textContent.trim());
      const idx = ths.indexOf(${q(colName)}) + 1;
      const rows = t.querySelectorAll(':scope > tbody:first-of-type > tr');
      const td = rows[rows.length - 1].querySelector('td:nth-child(' + idx + ')');
      return td ? td.textContent.trim() : null; })()`);
  const firstRowCell = (tableId, colName) => cellText(tableId, colName, 1);
  const successMessage = (text) => evaluate(`(() => {
      const el = document.querySelector('#gwt-debug-successMessage');
      return !!el && el.querySelector('span').textContent.includes(${q(text)}); })()`);
  const waitSuccess = async (text) => {
    await waitFor(`(() => { const el = document.querySelector('#gwt-debug-successMessage'); return !!el; })()`, 'success message');
    return successMessage(text);
  };

  const navigate = async (hash) => {
    await send('Page.navigate', { url: BASE + hash });
    await sleep(1200);
  };
  const scenario = async (name, fn) => {
    try {
      await fn();
      results.push(['PASS', name]);
    } catch (e) {
      failures++;
      results.push(['FAIL', name + ' :: ' + e.message]);
    }
  };
  const assert = (cond, msg) => { if (!cond) throw new Error('assertion failed: ' + msg); };

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Page.enable');
  // Clear messages/state between scenarios by reloading the page.

  await scenario('Menubar links carry the GWT history tokens', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'manufacturer table');
    const hrefs = await evaluate(`[...document.querySelectorAll('#gwt-debug-menubar a')].map(a => a.getAttribute('href'))`);
    assert(hrefs.some((h) => h.includes('manufacturer')), 'manufacturer link ' + hrefs);
    assert(hrefs.some((h) => h.includes('rating')), 'rating link ' + hrefs);
    assert(hrefs.some((h) => h.includes('report')), 'report link ' + hrefs);
    await evaluate(`document.querySelector('#gwt-debug-menubar a[href*="report"]').click()`);
    await waitFor(`location.hash.includes('report')`, 'hash report');
    await waitFor(exists('#gwt-debug-reports'), 'report table');
  });

  await scenario('Manufacturers: create button shows the editor', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    await clickSel('#gwt-debug-create-manufacturer');
    await waitFor(isVisible('#gwt-debug-manufacturer-editor'), 'editor');
  });

  await scenario('Manufacturers: close leaves table unaltered', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    const before = await rowCount('gwt-debug-manufacturers'.replace('gwt-debug-', '').replace('manufacturers', 'manufacturers'));
    await clickSel('#gwt-debug-create-manufacturer');
    await waitFor(isVisible('#gwt-debug-manufacturer-editor'), 'editor');
    await typeInto('#gwt-debug-manufacturer-input', 'Ford');
    await clickSel('#gwt-debug-manufacturer-close');
    await waitFor(`!document.querySelector('#gwt-debug-manufacturer-editor')`, 'editor closed');
    assert((await rowCount('manufacturers')) === before, 'row count changed');
  });

  await scenario('Manufacturers: save adds a row at the end with a success message', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    const before = await rowCount('manufacturers');
    await clickSel('#gwt-debug-create-manufacturer');
    await waitFor(isVisible('#gwt-debug-manufacturer-editor'), 'editor');
    await typeInto('#gwt-debug-manufacturer-input', 'Plymouth');
    await clickSel('#gwt-debug-manufacturer-save');
    assert(await waitSuccess('saved'), 'success message containing saved');
    await waitFor(`document.querySelectorAll('#gwt-debug-manufacturers > tbody:first-of-type > tr').length === ${before + 1}`, 'row added');
    assert((await lastRowCell('manufacturers', 'Name')) === 'Plymouth', 'last manufacturer is Plymouth');
  });

  await scenario('Manufacturers: editing the first row updates it', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    await clickSel('#gwt-debug-manufacturers > tbody tr:first-child td:nth-last-child(2) button');
    await waitFor(isVisible('#gwt-debug-manufacturer-editor'), 'editor');
    await typeInto('#gwt-debug-manufacturer-input', 'Ford');
    await clickSel('#gwt-debug-manufacturer-save');
    assert(await waitSuccess('saved'), 'success message containing saved');
    await waitFor(`document.querySelector('#gwt-debug-manufacturers > tbody tr:first-child td:nth-child(2)').textContent.trim() === 'Ford'`, 'first row Ford');
  });

  await scenario('Manufacturers: delete first row asks for confirmation and removes it', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    const before = await rowCount('manufacturers');
    await evaluate(`window.__confirmAsked = 0; window.confirm = function (msg) { window.__confirmAsked++; return true; }; true`);
    await clickSel('#gwt-debug-manufacturers > tbody td:last-child button');
    await waitFor(`document.querySelectorAll('#gwt-debug-manufacturers > tbody:first-of-type > tr').length === ${before - 1}`, 'row removed');
    assert((await evaluate('window.__confirmAsked')) === 1, 'confirm asked once');
  });

  await scenario('Ratings: create a rating', async () => {
    await navigate('#rating');
    await waitFor(exists('#gwt-debug-ratings'), 'ratings table');
    const before = await rowCount('ratings');
    await clickSel('#gwt-debug-ratingCreate');
    await waitFor(isVisible('#gwt-debug-ratingInput'), 'rating input');
    await typeInto('#gwt-debug-ratingInput', '10');
    await clickSel('#gwt-debug-ratingSave');
    await waitFor(`!document.querySelector('#gwt-debug-ratingSave')`, 'editor closed');
    assert(await waitSuccess('saved'), 'success message');
    await waitFor(`document.querySelectorAll('#gwt-debug-ratings > tbody:first-of-type > tr').length === ${before + 1}`, 'rating row added');
  });

  await scenario('Ratings: delete first rating', async () => {
    await navigate('#rating');
    await waitFor(exists('#gwt-debug-ratings'), 'ratings table');
    const before = await rowCount('ratings');
    await evaluate(`window.confirm = function () { return true; }; true`);
    await clickSel('#gwt-debug-ratings > tbody td:last-child button');
    await waitFor(`document.querySelectorAll('#gwt-debug-ratings > tbody:first-of-type > tr').length === ${before - 1}`, 'rating removed');
  });

  await scenario('Reports: averages match the rating table', async () => {
    await navigate('#rating');
    await waitFor(exists('#gwt-debug-ratings'), 'ratings table');
    const n = await rowCount('ratings');
    const sums = {};
    for (let line = 1; line <= n; line++) {
      const car = await cellText('ratings', 'Car', line);
      const rating = Number(await cellText('ratings', 'Rating', line));
      const m = car.substring(0, car.indexOf('/'));
      sums[m] = sums[m] || { sum: 0, count: 0 };
      sums[m].sum += rating; sums[m].count++;
    }
    await navigate('#report');
    await waitFor(exists('#gwt-debug-reports'), 'report table');
    const rows = await rowCount('reports');
    assert(rows === Object.keys(sums).length, `report rows ${rows} vs ${Object.keys(sums).length}`);
    for (let line = 1; line <= rows; line++) {
      const manufacturer = await cellText('reports', 'Manufacturer', line);
      const avg = Number(await cellText('reports', 'Rating', line));
      const ref = sums[manufacturer].sum / sums[manufacturer].count;
      assert(Math.abs(avg - ref) < 0.001, `${manufacturer}: ${avg} vs ${ref}`);
    }
  });

  for (const [status, name] of results) console.log(status, name);
  console.log(failures === 0 ? 'ALL PASSED' : `${failures} FAILED`);
  ws.close();
  chrome.kill('SIGKILL');
  process.exit(failures === 0 ? 0 : 1);
}

main().catch((e) => { console.error('harness error', e); process.exit(2); });

