    await evaluate(`document.querySelector('#gwt-debug-menubar a[href*="report"]').click()`);
    await waitFor(`location.hash.includes('report')`, 'hash report');
    await waitFor(exists('#gwt-debug-reports'), 'report table');
  });

  await scenario('Manufacturers: create button shows the editor', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    await clickSel('#gwt-debug-create-manufacturer');
    await waitFor(isVisible('#gwt-debug-manufacturer-editor'), 'editor');
  });

  await scenario('Manufacturers: close leaves table unaltered', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    const before = await rowCount('gwt-debug-manufacturers'.replace('gwt-debug-', '').replace('manufacturers', 'manufacturers'));
    await clickSel('#gwt-debug-create-manufacturer');
    await waitFor(isVisible('#gwt-debug-manufacturer-editor'), 'editor');
    await typeInto('#gwt-debug-manufacturer-input', 'Ford');
    await clickSel('#gwt-debug-manufacturer-close');
    await waitFor(`!document.querySelector('#gwt-debug-manufacturer-editor')`, 'editor closed');
    assert((await rowCount('manufacturers')) === before, 'row count changed');
  });

  await scenario('Manufacturers: save adds a row at the end with a success message', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    const before = await rowCount('manufacturers');
    await clickSel('#gwt-debug-create-manufacturer');
    await waitFor(isVisible('#gwt-debug-manufacturer-editor'), 'editor');
    await typeInto('#gwt-debug-manufacturer-input', 'Plymouth');
    await clickSel('#gwt-debug-manufacturer-save');
    assert(await waitSuccess('saved'), 'success message containing saved');
    await waitFor(`document.querySelectorAll('#gwt-debug-manufacturers > tbody:first-of-type > tr').length === ${before + 1}`, 'row added');
    assert((await lastRowCell('manufacturers', 'Name')) === 'Plymouth', 'last manufacturer is Plymouth');
  });

  await scenario('Manufacturers: editing the first row updates it', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    await clickSel('#gwt-debug-manufacturers > tbody tr:first-child td:nth-last-child(2) button');
    await waitFor(isVisible('#gwt-debug-manufacturer-editor'), 'editor');
    await typeInto('#gwt-debug-manufacturer-input', 'Ford');
    await clickSel('#gwt-debug-manufacturer-save');
    assert(await waitSuccess('saved'), 'success message containing saved');
    await waitFor(`document.querySelector('#gwt-debug-manufacturers > tbody tr:first-child td:nth-child(2)').textContent.trim() === 'Ford'`, 'first row Ford');
  });

  await scenario('Manufacturers: delete first row asks for confirmation and removes it', async () => {
    await navigate('#manufacturer');
    await waitFor(exists('#gwt-debug-manufacturers'), 'table');
    const before = await rowCount('manufacturers');
    await evaluate(`window.__confirmAsked = 0; window.confirm = function (msg) { window.__confirmAsked++; return true; }; true`);
    await clickSel('#gwt-debug-manufacturers > tbody td:last-child button');
    await waitFor(`document.querySelectorAll('#gwt-debug-manufacturers > tbody:first-of-type > tr').length === ${before - 1}`, 'row removed');
    assert((await evaluate('window.__confirmAsked')) === 1, 'confirm asked once');
  });

  await scenario('Ratings: create a rating', async () => {
    await navigate('#rating');
    await waitFor(exists('#gwt-debug-ratings'), 'ratings table');
    const before = await rowCount('ratings');
    await clickSel('#gwt-debug-ratingCreate');
    await waitFor(isVisible('#gwt-debug-ratingInput'), 'rating input');
    await typeInto('#gwt-debug-ratingInput', '10');
    await clickSel('#gwt-debug-ratingSave');
    await waitFor(`!document.querySelector('#gwt-debug-ratingSave')`, 'editor closed');
    assert(await waitSuccess('saved'), 'success message');
    await waitFor(`document.querySelectorAll('#gwt-debug-ratings > tbody:first-of-type > tr').length === ${before + 1}`, 'rating row added');
  });

  await scenario('Ratings: delete first rating', async () => {
    await navigate('#rating');
    await waitFor(exists('#gwt-debug-ratings'), 'ratings table');
    const before = await rowCount('ratings');
    await evaluate(`window.confirm = function () { return true; }; true`);
    await clickSel('#gwt-debug-ratings > tbody td:last-child button');
    await waitFor(`document.querySelectorAll('#gwt-debug-ratings > tbody:first-of-type > tr').length === ${before - 1}`, 'rating removed');
  });

  await scenario('Reports: averages match the rating table', async () => {
    await navigate('#rating');
    await waitFor(exists('#gwt-debug-ratings'), 'ratings table');
    const n = await rowCount('ratings');
    const sums = {};
    for (let line = 1; line <= n; line++) {
      const car = await cellText('ratings', 'Car', line);
      const rating = Number(await cellText('ratings', 'Rating', line));
      const m = car.substring(0, car.indexOf('/'));
      sums[m] = sums[m] || { sum: 0, count: 0 };
      sums[m].sum += rating; sums[m].count++;
    }
    await navigate('#report');
    await waitFor(exists('#gwt-debug-reports'), 'report table');
    const rows = await rowCount('reports');
    assert(rows === Object.keys(sums).length, `report rows ${rows} vs ${Object.keys(sums).length}`);
    for (let line = 1; line <= rows; line++) {
      const manufacturer = await cellText('reports', 'Manufacturer', line);
      const avg = Number(await cellText('reports', 'Rating', line));
      const ref = sums[manufacturer].sum / sums[manufacturer].count;
      assert(Math.abs(avg - ref) < 0.001, `${manufacturer}: ${avg} vs ${ref}`);
    }
  });

  for (const [status, name] of results) console.log(status, name);
  console.log(failures === 0 ? 'ALL PASSED' : `${failures} FAILED`);
  ws.close();
  chrome.kill('SIGKILL');
  process.exit(failures === 0 ? 0 : 1);
}

main().catch((e) => { console.error('harness error', e); process.exit(2); });

