// Drives headless Chromium over CDP through the same scenarios as e2e/*.feature,
// using the same element ids / table xpaths / button selectors as the Selenium page objects.
const WebSocket = require('/work/node_modules/ws');
const { spawn } = require('child_process');

const BASE = 'http://localhost:8888/ng/';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const q = (s) => JSON.stringify(s);

let failures = 0;
const results = [];

async function main() {
  const profile = '/tmp/cr-profile-' + Date.now();
  const chrome = spawn('/usr/bin/chromium', [
    '--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
    '--remote-debugging-port=9333', '--user-data-dir=' + profile, '--window-size=1280,900', 'about:blank',
  ], { stdio: 'ignore' });

  let targets;
  for (let i = 0; i < 100; i++) {
    try { targets = await (await fetch('http://127.0.0.1:9333/json/list')).json(); break; } catch { await sleep(200); }
  }
  const page = targets.find((t) => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl, { perMessageDeflate: false });
  await new Promise((res, rej) => { ws.on('open', res); ws.on('error', rej); });

  let nextId = 0;
  const pending = new Map();
  ws.on('message', (m) => {
    const msg = JSON.parse(m);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  });
  const send = (method, params = {}) => new Promise((res) => {
    const id = ++nextId; pending.set(id, res); ws.send(JSON.stringify({ id, method, params }));
  });
  const evaluate = async (expr) => {
    const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
    if (r.result.exceptionDetails) throw new Error('JS error: ' + JSON.stringify(r.result.exceptionDetails).slice(0, 500));
    return r.result.result.value;
  };
  const waitFor = async (expr, what, timeout = 10000) => {
    const end = Date.now() + timeout;
    while (Date.now() < end) { if (await evaluate(expr)) return; await sleep(100); }
    throw new Error('timeout waiting for ' + what);
  };
  const isVisible = (sel) => `(() => { const el = document.querySelector(${q(sel)}); if (!el) return false;
      const r = el.getBoundingClientRect(); return r.width > 0 && r.height > 0; })()`;
  const exists = (sel) => `!!document.querySelector(${q(sel)})`;
  const clickSel = async (sel) => {
    await waitFor(`${isVisible(sel)} && !document.querySelector(${q(sel)}).disabled`, 'clickable ' + sel);
    await evaluate(`document.querySelector(${q(sel)}).click()`);
  };
  const typeInto = async (sel, text) => {
    await waitFor(isVisible(sel), 'visible ' + sel);
    await evaluate(`(() => { const el = document.querySelector(${q(sel)}); el.focus(); try { el.select(); } catch (e) {} return true; })()`);
    await send('Input.insertText', { text });
  };
  // Mirrors PageWithEditTable: rows are tbody[1]/tr, cell index comes from thead th text.
  const rowCount = (tableId) => evaluate(`document.querySelectorAll(${q('#' + tableId + ' > tbody:first-of-type > tr')}).length`);
  const cellText = (tableId, colName, row) => evaluate(`(() => {
      const t = document.getElementById(${q(tableId)});
      const ths = [...t.querySelectorAll('thead th')].map(th => th.textContent.trim());
      const idx = ths.indexOf(${q(colName)}) + 1;
      const td = t.querySelector(':scope > tbody:first-of-type > tr:nth-child(${row}) > td:nth-child(' + idx + ')');
      return td ? td.textContent.trim() : null; })()`);
  const lastRowCell = (tableId, colName) => evaluate(`(() => {
      const t = document.getElementById(${q(tableId)});
      const ths = [...t.querySelectorAll('thead th')].map(th => th.textContent.trim());
      const idx = ths.indexOf(${q(colName)}) + 1;
      const rows = t.querySelectorAll(':scope > tbody:first-of-type > tr');
      const td = rows[rows.length - 1].querySelector('td:nth-child(' + idx + ')');
      return td ? td.textContent.trim() : null; })()`);
  const firstRowCell = (tableId, colName) => cellText(tableId, colName, 1);
  const successMessage = (text) => evaluate(`(() => {
      const el = document.querySelector('#gwt-debug-successMessage');
      return !!el && el.querySelector('span').textContent.includes(${q(text)}); })()`);
  const waitSuccess = async (text) => {
    await waitFor(`(() => { const el = document.querySelector('#gwt-debug-successMessage'); return !!el; })()`, 'success message');
    return successMessage(text);
  };

  const navigate = async (hash) => {
    await send('Page.navigate', { url: BASE + hash });
    await sleep(1200);
  };
  const scenario = async (name, fn) => {
    try {
      await fn();
      results.push(['PASS', name]);
    } catch (e) {
      failures++;
      results.push(['FAIL', name + ' :: ' + e.message]);
    }
  };
  const assert = (cond, msg) => { if (!cond) throw new Error('assertion failed: ' + msg); };

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Page.enable');
