// JSON shapes of the REST API (gwt/.../shared/dto/*.java, Jackson property names).

export interface Manufacturer {
  id?: number;
  name: string;
  cars?: Car[] | null;
}

export interface Car {
  id?: number;
  model: string;
  manufacturer: Manufacturer;
  ratings?: Rating[];
  carProperties?: unknown;
}

export interface Rating {
  id?: number;
  rating: number;
  car: Car;
}

// GET /api/manufacturers/ratings
export interface ManufacturerRating {
  manufacturer: string;
  rating: number | null;
}

/** Label used for a car everywhere in the app: "Manufacturer/Model" (same as RatingDto.toString). */
export function carLabel(car: Car): string {
  return `${car.manufacturer.name}/${car.model}`;
}

