// Minimal Selenium JSON-Wire server backed by headless Chromium (CDP).
// Only implements what the e2e page objects use; stands in for chromedriver, which is not installed here.
const http = require('http');
const WebSocket = require('/work/node_modules/ws');
const { spawn } = require('child_process');

const PORT = 9515;
const CDP_PORT = 9334;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let cdp;
let nextCdpId = 0;
const cdpPending = new Map();

async function startChrome() {
  const profile = '/tmp/cr-shim-' + Date.now();
  spawn('/usr/bin/chromium', ['--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage',
    `--remote-debugging-port=${CDP_PORT}`, `--user-data-dir=${profile}`, '--window-size=1280,900', 'about:blank'],
  { stdio: 'ignore' });
  let targets;
  for (let i = 0; i < 100; i++) {
    try { targets = await (await fetch(`http://127.0.0.1:${CDP_PORT}/json/list`)).json(); break; } catch { await sleep(200); }
