function handle(req, res) {
  let data = '';
  req.on('data', (c) => { data += c; });
  req.on('end', async () => {
    let body = {};
    try { body = data ? JSON.parse(data) : {}; } catch (e) { body = {}; }
    let out;
    try {
      out = await command(req.method, req.url.split('?')[0], body);
    } catch (e) {
      const status = e.status || (e.wd || UNKNOWN);
      out = { status, value: { message: e.message } };
      if (process.env.SHIM_DEBUG) console.error('shim error', req.method, req.url, e.message);
    }
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(out));
  });
}

(async () => {
  await startChrome();
  http.createServer(handle).listen(PORT, '127.0.0.1', () => console.log('shim listening on ' + PORT));
})();

